exercises.solution:
def find_first(items, predicate):
    for x in items:
        if predicate(x):
            return x
    return None

def partition(items, predicate):
    yes, no = [], []
    for x in items:
        (yes if predicate(x) else no).append(x)
    return yes, no

def wait_for(check, max_attempts):
    for attempt in range(1, max_attempts + 1):
        if check(attempt):
            return attempt
    return -1

